-- -----------------------------------
-- Table structure for `all_dvr_live`
-- -----------------------------------

DROP TABLE IF EXISTS `all_dvr_live`;
CREATE TABLE `all_dvr_live` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `UserName` varchar(50) DEFAULT NULL,
  `Password` varchar(50) DEFAULT NULL,
  `dvrname` varchar(30) DEFAULT NULL,
  `IPAddress` varchar(50) DEFAULT NULL,
  `port` int(10) DEFAULT NULL,
  `customer` varchar(20) DEFAULT NULL,
  `live` varchar(10) DEFAULT NULL,
  `status` varchar(11) DEFAULT NULL,
  `cam1` varchar(11) DEFAULT NULL,
  `cam2` varchar(11) DEFAULT NULL,
  `cam3` varchar(11) DEFAULT NULL,
  `cam4` varchar(11) DEFAULT NULL,
  `hdd` varchar(25) DEFAULT NULL,
  `latency` varchar(11) DEFAULT NULL,
  `cdate` datetime DEFAULT NULL,
  `login_status` int(11) DEFAULT NULL,
  `last_communication` datetime DEFAULT NULL,
  `atmid` varchar(40) DEFAULT NULL,
  `capacity` varchar(25) DEFAULT NULL,
  `freespace` varchar(25) DEFAULT NULL,
  `recording_from` varchar(30) DEFAULT NULL,
  `recording_to` varchar(30) DEFAULT NULL,
  `SN` int(11) DEFAULT NULL,
  `dvr_time` datetime DEFAULT NULL,
  `time_diff` varchar(20) DEFAULT NULL,
  `project` varchar(20) DEFAULT NULL,
  `ipcamport` varchar(10) DEFAULT NULL,
  `ipcamtype` varchar(20) DEFAULT NULL,
  `runby` varchar(20) DEFAULT NULL,
  `remarks` text,
  `cam5` varchar(30) DEFAULT NULL,
  `bank` varchar(200) DEFAULT NULL,
  `cdate1` datetime DEFAULT CURRENT_TIMESTAMP,
  `address` text,
  `unique_id` varchar(50) NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=MyISAM AUTO_INCREMENT=8399 DEFAULT CHARSET=latin1;

